import os
import shutil
import subprocess
import zipfile
import re

# Configuration
SOURCE_DIR = 'papers/all'
DEST_DIRS = {
    'LLM': ['llm', 'large language model', 'transformer', 'gpt', 'bert', 'attention', 'neural network', 'nlp', 'generative', 'token'],
    'trapped_ion_and_qc': ['trapped ion', 'quantum computing', 'qubit', 'paul trap', 'entanglement', 'fidelity', 'laser cooling', 'quantum gate', 'hyperfine', 'state preparation'],
    'black_hole': ['black hole', 'event horizon', 'singularity', 'gravitational', 'accretion', 'relativity', 'schwarzschild', 'kerr', 'astrophysics', 'hawking'],
    'DNA': ['dna', 'gene', 'genome', 'nucleotide', 'sequence', 'double helix', 'biology', 'protein', 'rna', 'genetic'],
    'music_history': ['music', 'composer', 'symphony', 'baroque', 'classical', 'jazz', 'opera', 'instrument', 'sonata', 'concerto', 'rhythm', 'melody']
}

FALLBACK_DIR = 'music_history'

def extract_text_from_pdf(filepath):
    try:
        result = subprocess.run(['pdftotext', filepath, '-'], capture_output=True, text=True, errors='ignore')
        return result.stdout.lower()
    except Exception as e:
        print(f"Error reading PDF {filepath}: {e}")
        return ""

def extract_text_from_docx(filepath):
    try:
        with zipfile.ZipFile(filepath) as z:
            xml_content = z.read('word/document.xml').decode('utf-8')
            text = re.sub('<[^>]+>', ' ', xml_content)
            return text.lower()
    except Exception as e:
        print(f"Error reading DOCX {filepath}: {e}")
        return ""

def extract_text_from_pptx(filepath):
    try:
        text = ""
        with zipfile.ZipFile(filepath) as z:
            for name in z.namelist():
                if name.startswith('ppt/slides/slide') and name.endswith('.xml'):
                    xml_content = z.read(name).decode('utf-8')
                    text += re.sub('<[^>]+>', ' ', xml_content)
        return text.lower()
    except Exception as e:
        print(f"Error reading PPTX {filepath}: {e}")
        return ""

def classify_file(text):
    scores = {category: 0 for category in DEST_DIRS}
    for category, keywords in DEST_DIRS.items():
        for keyword in keywords:
            scores[category] += text.count(keyword)

    # Find the category with the highest score
    best_category = max(scores, key=scores.get)

    # If all scores are 0, use fallback
    if scores[best_category] == 0:
        return FALLBACK_DIR

    return best_category

def main():
    if not os.path.exists(SOURCE_DIR):
        print(f"Source directory {SOURCE_DIR} does not exist.")
        return

    files = os.listdir(SOURCE_DIR)
    print(f"Found {len(files)} files to process.")

    for filename in files:
        filepath = os.path.join(SOURCE_DIR, filename)
        if not os.path.isfile(filepath):
            continue

        text = ""
        if filename.lower().endswith('.pdf'):
            text = extract_text_from_pdf(filepath)
        elif filename.lower().endswith('.docx'):
            text = extract_text_from_docx(filepath)
        elif filename.lower().endswith('.pptx'):
            text = extract_text_from_pptx(filepath)
        else:
            print(f"Skipping unknown file type: {filename}")
            continue

        category = classify_file(text)
        dest_path = os.path.join(category, filename)

        print(f"Moving {filename} to {category}")
        shutil.move(filepath, dest_path)

if __name__ == '__main__':
    main()
